import{_ as r,a as o}from"./chunks/Install45.BdJsAdnu.js";import{_ as a,o as i,c as t,a3 as s}from"./chunks/framework.g9mfNVRQ.js";const v=JSON.parse('{"title":"Prérequis","description":"","frontmatter":{"source_hash":"a6ac1989f7","source_commit":"0bbdbd2"},"headers":[],"relativePath":"fr/install/prerequisites.md","filePath":"fr/install/prerequisites.md"}'),l={name:"fr/install/prerequisites.md"};function n(p,e,c,u,d,m){return i(),t("div",null,[...e[0]||(e[0]=[s('<p>Vous avez besoin d&#39;un téléphone Android.</p><p><img src="https://www.android.com/static/images/logos/andy-peace.png" alt="https://www.android.com/static/images/logos/andy-peace.png"></p><ul><li>La version minimale d&#39;Android prise en charge est la 8.0 (la prise en charge d&#39;Android 7 a été retirée avec la version du <a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.12" target="_blank" rel="noreferrer">12 juillet 2026</a>).</li><li>Si vous connectez xDrip à un capteur, votre téléphone doit prendre en charge le Bluetooth Low Energy (BLE) : vous pouvez le vérifier avec des utilitaires <a href="https://play.google.com/store/apps/details?id=com.treeteam.blechecker" target="_blank" rel="noreferrer">comme celui-ci</a>.</li><li>Si vous voulez utiliser la fonction principal - abonné intégrée à xDrip (appelée xDrip Sync), les deux téléphones doivent avoir les <a href="https://play.google.com/store/apps/details?id=com.google.android.gms" target="_blank" rel="noreferrer">Services Google Play</a> installés.</li><li>Pour utiliser les fonctions de scan NFC des capteurs Libre 1 et 2/2+ (UE uniquement), ou pour vous connecter directement à un capteur Libre 2/2+ (UE), votre téléphone doit disposer d&#39;un lecteur NFC compatible.</li><li>Si vous utilisez Android 16 ou plus récent, assurez-vous d&#39;utiliser une version récente de xDrip (au moins la <a href="./download.html#latest-release">dernière version stable</a>, nous en parlerons plus loin : continuez la lecture).</li></ul><h3 id="google-play-services" tabindex="-1">Services Google Play <a class="header-anchor" href="#google-play-services" aria-label="Permalink to &quot;Services Google Play {#google-play-services}&quot;">​</a></h3><p>​ <img src="http://www.gstatic.com/android/market_images/web/favicon_v3.ico" alt="http://www.gstatic.com/android/market_images/web/favicon_v3.ico"></p><p>Si votre téléphone n&#39;a pas les Services Google Play (certains téléphones Huawei et chinois ne les ont pas), vous pouvez quand même utiliser xDrip, mais pas la fonction xDrip Sync qui en dépend, comme indiqué ci-dessus.<br> Vous pouvez rencontrer des problèmes inattendus avec des systèmes alternatifs basés sur Android.<br> Dans ce cas, assurez-vous de <a href="./../use/sync.html#disable-sync">désactiver les fonctions de synchronisation</a>.</p><h3 id="family-link" tabindex="-1">Family Link <a class="header-anchor" href="#family-link" aria-label="Permalink to &quot;Family Link {#family-link}&quot;">​</a></h3><img src="https://families.google/intl/it_ALL/familylink/static/img/fl-icon.svg" style="zoom:25%;"><p>Pour installer xDrip sur un téléphone supervisé par <a href="https://families.google.com/families" target="_blank" rel="noreferrer">Google Family Link</a>, <strong>vous devez le désactiver</strong> le temps d&#39;installer l&#39;application.<br> Si vous voulez le réactiver ensuite, assurez-vous que xDrip a toutes les autorisations et aucune limite de temps.</p><h3 id="work-profile" tabindex="-1">Profil professionnel <a class="header-anchor" href="#work-profile" aria-label="Permalink to &quot;Profil professionnel {#work-profile}&quot;">​</a></h3><img src="https://developer.android.com/static/images/work/cards/briefcase_600px.png" style="zoom:15%;"><p>Si vous utilisez un téléphone géré par votre entreprise, vous ne pourrez peut-être pas installer xDrip à cause des règles de l&#39;entreprise.</p><p>Vous pouvez essayer d&#39;installer l&#39;application depuis un ordinateur avec <a href="./../troubleshoot/ADB.html#smartphone">Android Debug</a>, après avoir activé les options pour les développeurs sur votre téléphone. N&#39;oubliez pas de supprimer xDrip de votre profil professionnel si nécessaire, car il peut être installé dans les deux environnements.</p><h3 id="phone-time-accuracy" tabindex="-1">Précision de l&#39;heure du téléphone <a class="header-anchor" href="#phone-time-accuracy" aria-label="Permalink to &quot;Précision de l&#39;heure du téléphone {#phone-time-accuracy}&quot;">​</a></h3><p>Synchronisez l&#39;horloge de votre téléphone avec le réseau (Paramètres Android -&gt; <a href="https://support.google.com/android/answer/2841106" target="_blank" rel="noreferrer">Date et heure</a>).<br> Vérifiez que vous êtes sur le bon fuseau horaire et que l&#39;heure d&#39;été y correspond.</p><img src="'+r+'" style="zoom:65%;"><h3 id="energy-savings" tabindex="-1">Économies d&#39;énergie <a class="header-anchor" href="#energy-savings" aria-label="Permalink to &quot;Économies d&#39;énergie {#energy-savings}&quot;">​</a></h3><p><strong><a href="./../troubleshoot/savings.html">Désactivez</a></strong> tous les réglages d&#39;économie d&#39;énergie/de batterie d&#39;Android avant d&#39;installer xDrip.<br> Vous pourrez essayer d&#39;en rétablir certains après avoir vérifié que xDrip fonctionne correctement, mais <strong>n&#39;optimisez jamais</strong> xDrip.</p><br><h3 id="play-protect" tabindex="-1">Play Protect <a class="header-anchor" href="#play-protect" aria-label="Permalink to &quot;Play Protect {#play-protect}&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>En général, Google Play Protect ne bloque pas xDrip, mais il peut bloquer <a href="./../use/OOP.html">OOP</a>.</p></div><p>Si xDrip s&#39;arrête de fonctionner chaque nuit entre minuit et 3 h du matin, essayez de désactiver Google Play Protect.<br> Comme il s&#39;agit d&#39;une fonction de sécurité importante pour votre téléphone, évitez d&#39;ouvrir des liens inconnus et de télécharger des jeux : gardez votre téléphone CGM aussi sûr que possible si vous décidez de désactiver Play Protect.</p><p>Vous trouverez Google Play Protect dans les paramètres de l&#39;application Play Store de votre téléphone.</p><img src="'+o+'" style="zoom:75%;"><br><p><a href="./download.html">Passer au téléchargement de xDrip</a></p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.07.15" target="_blank" rel="noreferrer"><em>Dernière modification le 18/7/2026</em></a></p>',28)])])}const f=a(l,[["render",n]]);export{v as __pageData,f as default};
